B.W7=new A.ba(B.Xb,["11 Farkl\u0131 Arazi","Her biyoma \xf6zg\xfc 3+ yap\u0131","\xc7\xf6l yaz\u0131n co\u015far, Tundra k\u0131\u015fa diren\xe7lidir"],t.l)
B.Uy=s(["Her biyomun kendine has binalar\u0131 vard\u0131r; \xf6rne\u011fin Vaha Sarn\u0131c\u0131 yaln\u0131zca \xc7\xf6l karolar\u0131na kurulabilir."],t.s)
B.Uf=s(["Specific buildings require native biomes, such as Oasis Cisterns in Deserts."],t.s)
